solution.javascript:
function networkDelayTime(times, n, k) {
  const adj = Array.from({length: n+1}, () => []);
  for (const [u,v,w] of times) adj[u].push([v, w]);
  const dist = Array(n+1).fill(Infinity); dist[k] = 0;
  const pq = [[0, k]];
  while (pq.length) {
    pq.sort((a,b) => b[0] - a[0]);
    const [d, u] = pq.pop();
    if (d > dist[u]) continue;
    for (const [v, w] of adj[u]) if (dist[u] + w < dist[v]) { dist[v] = dist[u] + w; pq.push([dist[v], v]); }
  }
  const maxD = Math.max(...dist.slice(1));
  return maxD === Infinity ? -1 : maxD;
}

solution.cpp:
int networkDelayTime(vector<vector<int>>& times, int n, int k) {
    vector<vector<pair<int,int>>> adj(n+1);
    for (auto& t : times) adj[t[0]].push_back({t[1], t[2]});
    vector<int> dist(n+1, INT_MAX); dist[k] = 0;
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq; pq.push({0, k});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;
        for (auto [v, w] : adj[u]) if (dist[u] + w < dist[v]) { dist[v] = dist[u] + w; pq.push({dist[v], v}); }
    }
    int maxD = *max_element(dist.begin()+1, dist.end());
    return maxD == INT_MAX ? -1 : maxD;
}
